title:
const double = x => x * 2
const addOne = x => x + 1
const square = x => x * x

// compose: square → addOne → double 순으로 실행
const transform = compose(double, addOne, square)
transform(3)  // double(addOne(square(3))) = double(addOne(9)) = double(10) = 20

// pipe: double → addOne → square 순으로 실행 (읽기 더 쉬움)
const transform = pipe(double, addOne, square)
transform(3)  // square(addOne(double(3))) = square(addOne(6)) = square(7) = 49

